"""Build portable static course. Python standard library only."""
import json,html,shutil,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'docs'; OUT.mkdir(exist_ok=True)
L=json.loads((ROOT/'content/course.json').read_text()); R=json.loads((ROOT/'content/references.json').read_text()); RM={r['id']:r for r in R}
V=json.loads((ROOT/'content/visuals.json').read_text())
def e(v): return html.escape(str(v),quote=True)
def paras(s): return ''.join('<p>'+e(p)+'</p>' for p in s.split('\n\n'))
def refitems(ids):
 return '<ol class="references">'+''.join(f'<li id="ref-{e(i)}"><a href="{e(RM[i]["url"])}" target="_blank" rel="noopener noreferrer">{e(RM[i]["apa"])}</a><small>{e(RM[i]["note"])}</small></li>' for i in ids)+'</ol>'
def shell(title,body,current='index',description=None):
 nav=[('index','Beranda','⌂'),('pertemuan','Pertemuan','▦'),('peta','Peta belajar','◇'),('kasus','Kasus & aktivitas','◉'),('glosarium','Glosarium','Aa'),('referensi','Referensi & regulasi','↗'),('tentang','Panduan kuliah','ⓘ')]
 links=''.join(f'<a href="{id}.html"'+(' aria-current="page"' if current==id else '')+f'><span aria-hidden="true">{ico}</span>{name}</a>' for id,name,ico in nav)
 return f'''<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(description or title+' — Pengantar Ilmu Pendidikan S1 PIAUD UNISMAM.')}"><meta name="theme-color" content="#164e41"><title>{e(title)} · Ruang PIAUD</title><link rel="icon" href="assets/icon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script src="assets/app.js" defer></script><noscript><style>.sidebar{{position:static;width:auto;transform:none;visibility:visible}}.page{{margin-left:0}}.mobile{{display:none}}.side-bottom{{display:none}}</style></noscript></head><body><a class="skip" href="#main">Langsung ke isi</a><header class="mobile"><a href="index.html">Ruang PIAUD</a><button id="menu-toggle" aria-expanded="false" aria-controls="sidebar">Menu ☰</button></header><aside id="sidebar" class="sidebar"><a class="brand" href="index.html"><img src="assets/icon.svg" alt="" width="42" height="42"><span>Ruang PIAUD<small>Belajar menjadi pendidik.</small></span></a><div class="nav-label">PENGANTAR ILMU PENDIDIKAN</div><nav aria-label="Menu utama">{links}</nav><div class="side-bottom"><div class="progress-label"><span>Langkah belajar Anda</span><strong id="progress-count">0/14</strong></div><progress id="course-progress" max="14" value="0" aria-label="Unit yang ditandai selesai"></progress><p>Catatan pribadi di perangkat ini.<br>Bukan nilai atau kehadiran.</p><a href="tentang.html#data">Kelola data belajar →</a></div></aside><div class="page"><div class="topbar"><span>S1 PIAUD <b> / </b> UNISMAM Jambi</span><span class="edition">EDISI 1.1 · 2026</span></div><main id="main" tabindex="-1">{body}</main><footer><span>Pengantar Ilmu Pendidikan · Jules Nurhatmi, M.Pd.</span><a href="tentang.html">Panduan & atribusi</a><a href="https://github.com/julesnh21/pengantar-ilmu-pendidikan-piaud" target="_blank" rel="noopener noreferrer">Repositori GitHub ↗</a></footer></div></body></html>'''
def write(name,body,current=None,title=None): (OUT/(name+'.html')).write_text(shell(title or name,body,current or name))
def heading(k,t,p): return f'<div class="page-heading"><span class="eyebrow">{e(k)}</span><h1>{e(t)}</h1><p>{e(p)}</p></div>'
def card(l):
 return f'<a class="lesson-card" href="{l["id"]}.html" data-search="{e((l["title"]+" "+l["summary"]+" "+" ".join(s["title"]+" "+s["text"] for s in l["sections"])).lower())}"><img class="card-scene" src="{V[l["id"]]["image"]}" alt="" loading="lazy" width="1536" height="1024"><div class="card-meta"><span>PERTEMUAN {l["slot"]:02}</span><span class="done-dot" data-done="{l["id"]}"></span></div><h3>{e(l["title"])}</h3><p>{e(l["summary"])}</p><span class="card-link">Pelajari materi <span aria-hidden="true">↗</span></span></a>'
hero='''<section class="hero"><div class="hero-copy"><span class="eyebrow">RUANG BELAJAR CALON PENDIDIK</span><h1>Memahami pendidikan.<br><em>Menemani anak bertumbuh.</em></h1><p>Jelajahi konsep, baca situasi nyata, dan bangun alasan di balik setiap keputusan sebagai calon pendidik anak usia dini.</p><div class="actions"><a class="button" href="hakikat.html">Mulai belajar <span aria-hidden="true">→</span></a><a class="button ghost" href="peta.html">Lihat peta belajar</a></div><div class="hero-tags"><span>14 unit materi</span><span>Kasus PAUD & RA</span><span>14 kasus bergambar</span></div></div><img class="hero-art" src="assets/scenes/manusia.webp" alt="Calon pendidik mengamati anak membangun dengan balok dan mendapatkan dukungan guru." width="1536" height="1024"></section>'''
body=hero+'''<section class="intro-strip"><span class="flower" aria-hidden="true">✳</span><div><strong>Dari teori menuju pertimbangan yang bermakna.</strong><p>Setiap unit membawa Anda dari pertanyaan pemantik ke konsep, penerapan, latihan, dan refleksi.</p></div><a href="tentang.html">Cara belajar →</a></section><section><div class="section-title"><div><span class="eyebrow">PERJALANAN SEMESTER</span><h2>Tiga ruang untuk bertumbuh</h2></div><a href="pertemuan.html">Semua pertemuan →</a></div><div class="path-grid"><a href="pertemuan.html#fondasi"><span class="path-num">01</span><h3>Memahami fondasi</h3><p>Hakikat, manusia, tujuan, landasan, pemikiran, dan sistem pendidikan.</p><small>Pertemuan 1–7</small></a><a href="pertemuan.html#aud"><span class="path-num">02</span><h3>Membaca dunia anak</h3><p>PAUD, nilai Islam, relasi pedagogis, serta bermain dan pengalaman.</p><small>Pertemuan 9–12</small></a><a href="pertemuan.html#profesi"><span class="path-num">03</span><h3>Menimbang tindakan</h3><p>Kebudayaan, tantangan digital, dan keputusan profesional yang beralasan.</p><small>Pertemuan 13–15</small></a></div></section><section><div class="section-title"><div><span class="eyebrow">LANGKAH PERTAMA</span><h2>Mulai dari pertanyaan mendasar</h2></div></div><div class="cards">'''+''.join(card(l) for l in L[:3])+'''</div></section><section class="case-feature"><span class="eyebrow">COBA PIKIRKAN</span><h2>“Anak yang diam pasti sedang belajar.”<br>Benarkah demikian?</h2><p>Ketertiban belum cukup menjadi bukti pemahaman. Belajar membaca pengalaman anak dimulai dengan memeriksa asumsi kita sendiri.</p><a class="button light" href="hakikat.html#kasus">Telusuri kasus pertama →</a></section>'''
write('index',body,title='Beranda')
body=heading('DAFTAR PERTEMUAN','Belajar selangkah demi selangkah','Peta 16 pertemuan: 14 unit materi, UTS, dan UAS. Pilih unit untuk membuka tujuan, materi, ilustrasi, latihan, serta referensi.')+'<label class="search-label" for="search">Cari topik atau istilah dalam materi</label><input id="search" class="search" type="search" placeholder="Misalnya: bermain, fitrah, regulasi…"><p id="search-result" role="status" aria-live="polite"></p>'
for id,title,items in [('fondasi','01 · Fondasi ilmu pendidikan',[l for l in L if l['slot']<8]),('aud','02 · Konteks PAUD dan PIAUD',[l for l in L if 9<=l['slot']<=12]),('profesi','03 · Kebudayaan dan profesionalisme',[l for l in L if l['slot']>=13])]:
 body+=f'<section class="lesson-group" id="{id}"><h2>{title}</h2><div class="cards">'+''.join(card(l) for l in items)+'</div></section>'
 if id=='fondasi': body+='<a class="assessment-link" href="uts.html"><strong>08 · UTS</strong><span>Analisis fondasi pendidikan melalui kasus →</span></a>'
body+='<a class="assessment-link" href="uas.html"><strong>16 · UAS</strong><span>Sintesis konsep dan keputusan pedagogis →</span></a><noscript><p>Pencarian membutuhkan JavaScript. Seluruh materi tetap dapat dibaca melalui tautan di atas.</p></noscript>'
