for n,l in enumerate(L):
 v=V[l["id"]]
 ids=['tujuan','kasus','persoalan','peta-konsep']+[f'materi-{i}' for i in range(1,len(l['sections'])+1)]+['kembali','bandingkan','latihan','refleksi','intisari','sumber']
 labels=['Tujuan belajar','Kasus bergambar','Persoalan konseptual','Baca peta konsep']+[s['title'] for s in l['sections']]+['Kembali ke kasus','Bandingkan tindakan','Latihan & cek pemahaman','Refleksi','Intisari','Referensi']
 toc='<nav class="toc" aria-label="Daftar isi pertemuan"><strong>DALAM PERTEMUAN INI</strong>'+''.join(f'<a href="#{i}">{e(t)}</a>' for i,t in zip(ids,labels))+'</nav>'
 b=f'<a class="back" href="pertemuan.html">← Semua pertemuan</a>'+heading(f'PERTEMUAN {l["slot"]:02} · 100 MENIT',l['title'],l['summary'])
 b+='<div class="lesson-tools"><button class="print-button" type="button">Cetak materi</button><span>Mandiri atau bersama dosen · Tidak merekam nilai</span></div><div class="reading-layout"><article class="reading">'
 b+=f'<section id="tujuan" class="goals"><span class="eyebrow">SETELAH BELAJAR, ANDA MAMPU</span><h2>Tujuan pembelajaran</h2><ol>'+''.join('<li>'+e(g)+'</li>' for g in l['goals'])+'</ol></section>'
 b+=f'<section id="kasus" class="visual-case"><div class="visual-heading"><span class="eyebrow">01 · AMATI ADEGAN</span><h2>{e(l["question"])}</h2></div><figure class="scene-figure"><a href="{v["image"]}" target="_blank" rel="noopener noreferrer" aria-label="{e(v["alt"])} Buka ilustrasi ukuran penuh."><img src="{v["image"]}" alt="{e(v["alt"])}" width="1536" height="1024" fetchpriority="high"></a><figcaption>Gambar {l["slot"]}.1 · Ilustrasi rekaan berbantuan AI, bukan dokumentasi anak atau bukti penelitian. Ketuk gambar untuk memperbesar.</figcaption></figure><div class="case-narrative"><span class="eyebrow">BACA KONTEKSNYA</span>{paras(l["case"])}<div class="observe"><strong>Amati sebelum menyimpulkan</strong><ol>'+''.join('<li>'+e(q)+'</li>' for q in v['observe'])+'</ol></div></div></section>' 
 b+='<section id="persoalan"><h2>Temukan persoalan konseptual</h2><p>Sebelum membaca penjelasan, pisahkan kejadian yang dinyatakan dalam kasus dari dugaan Anda. Gunakan pertanyaan berikut untuk menyiapkan analisis.</p><ol><li>Apa tujuan pendidikan yang sedang dipertaruhkan?</li><li>Pengalaman apa yang dialami anak, dan informasi apa yang belum tersedia?</li><li>Konsep atau jenis sumber apa yang diperlukan untuk menilai tindakan pendidik?</li></ol></section>'
 b+=f'<section id="peta-konsep" class="concept-section"><span class="eyebrow">02 · HUBUNGKAN DENGAN KONSEP</span><h2>{e(v["center"])}</h2><figure class="concept-figure"><img src="assets/{l["id"]}.svg" alt="{e(v["relation"])} Unsur: {e("; ".join(v["nodes"]))}." width="480" height="430" loading="lazy"><figcaption>Gambar {l["slot"]}.2 · Sintesis pedagogis penyusun; bukan reproduksi model baku.</figcaption></figure><div class="visual-reading"><strong>Cara membaca visual</strong><p>{e(v["read"])}</p><p>{e(v["relation"])}</p></div></section>' 
 for i,s in enumerate(l['sections'],1):
  b+=f'<section id="materi-{i}"><span class="sub-number">{i:02} / MATERI INTI</span><h2>{e(s["title"])}</h2>{paras(s["text"])}</section>'
  if i==2:b+='<aside class="pause"><strong>Jeda memahami</strong><p>Jelaskan hubungan dua konsep yang baru Anda baca dengan satu contoh AUD. Tandai bagian yang masih berupa dugaan, lalu lanjutkan membaca.</p></aside>'
 b+=f'<section id="kembali"><span class="eyebrow">DARI KONSEP KE TINDAKAN</span><h2>Kembali ke kasus</h2>{paras(l["analysis"])}<p class="note">Analisis ini merupakan contoh penalaran pedagogis. Pada situasi nyata, keputusan memerlukan informasi tentang anak dan konteks lembaga.</p></section>'
 b+='<section id="bandingkan" class="comparison-section"><span class="eyebrow">03 · TIMBANG TINDAKAN PENDIDIK</span><h2>Satu kasus, dua cara merespons</h2><p>Gunakan teori pada materi di atas untuk memeriksa alasan dan akibat yang mungkin muncul. Alternatif ini merupakan contoh telaah, bukan resep untuk semua anak.</p><div class="action-comparison">'
 for key,title in [('a','A · Perlu ditelaah'),('b','B · Alternatif untuk dipertimbangkan')]:
  act=v[key]
  b+=f'<div class="action-card action-{key}"><span class="action-badge">{title}</span><h3>{e(act[0])}</h3><p>{e(act[1])}</p><div class="evidence"><span aria-hidden="true">↓</span><strong>Perhatikan buktinya</strong><p>{e(act[2])}</p></div></div>'
 b+=f'</div><div class="visual-exercise"><span class="eyebrow">COBA MEMBACA ULANG GAMBAR</span><h3>Dari melihat ke beralasan</h3><p>{e(v["task"])}</p><details><summary>Buka contoh penalaran setelah mencoba</summary><p>{e(v["answer"])}</p></details><p class="note">Dasar konsep dan sitasi: baca materi inti serta <a href="#sumber">referensi unit ini</a>. Adegan dan alternatif merupakan penerapan ilustratif penyusun.</p></div></section>'
 b+=f'<section id="latihan"><h2>Latihan terbimbing</h2>{paras(l["guided"])}<h3>Latihan mandiri</h3>{paras(l["independent"])}<div class="self-check"><strong>Periksa kualitas jawaban Anda</strong><ul><li>Konsep digunakan dengan tepat dan dijelaskan hubungannya dengan kasus.</li><li>Fakta dipisahkan dari interpretasi; sumber mendukung jenis klaimnya.</li><li>Tindakan konkret, menghargai anak, dan memiliki cara peninjauan.</li></ul></div>'
 b+=f'<form class="quiz" data-answer="{l["answer"]}"><fieldset><legend>{e(l["quiz"][0])}</legend>'+''.join(f'<label><input type="radio" name="answer" value="{i}" required> {e(o)}</label>' for i,o in enumerate(l['quiz'][1:]))+f'</fieldset><button type="submit" class="button">Periksa alasan</button><p class="feedback" role="status" aria-live="polite" data-explanation="{e(l["explanation"])}"></p></form><details><summary>Lihat pembahasan</summary><p>{e(l["quiz"][l["answer"]+1])}</p><p>{e(l["explanation"])}</p></details></section>'
 b+=f'<section id="refleksi"><h2>Refleksi calon pendidik</h2><p class="reflection-prompt">{e(l["reflection"])}</p><label for="note-{l["id"]}">Catatan pribadi (gunakan kasus rekaan; jangan tulis identitas anak)</label><textarea id="note-{l["id"]}" data-note="{l["id"]}" rows="5" placeholder="Pemahaman saya berubah ketika…"></textarea><p class="save-status" role="status" aria-live="polite">Catatan hanya disimpan di peramban ini. Tidak dikirim kepada dosen.</p></section>'
 b+='<section id="intisari"><h2>Intisari dan tindak lanjut</h2><ul>'+''.join('<li>'+e(g)+'</li>' for g in l['takeaways'])+'</ul><p>Uji kembali pemahaman di atas melalui latihan mandiri. Jika alasan Anda belum menghubungkan konsep dan tindakan, baca ulang submateri terkait sebelum menandai selesai.</p></section>'
 b+=f'<section id="sumber"><h2>Referensi dan bacaan pendamping</h2><p>Sumber untuk klaim khusus disebut pada uraian. Buku pendamping tidak dikutip langsung. Jenis dan batas penggunaan setiap rujukan dijelaskan di bawah.</p>{refitems(l["refs"])}</section><div class="completion"><label><input type="checkbox" data-complete="{l["id"]}"> Saya telah membaca dan mengerjakan refleksi unit ini</label></div>'
 prev=L[n-1] if n else None; nex=L[n+1] if n+1<len(L) else None
 b+='<nav class="prevnext" aria-label="Navigasi materi">'+(f'<a href="{prev["id"]}.html">← {e(prev["title"])}</a>' if prev else '<a href="index.html">← Beranda</a>')+(f'<a href="{nex["id"]}.html">{e(nex["title"])} →</a>' if nex else '<a href="uas.html">Sintesis UAS →</a>')+'</nav></article>'+toc+'</div>'
