for name,slot,title,prompt,scope in [('uts',8,'UTS · Analisis fondasi pendidikan','Sebuah RA menilai keberhasilan dari kecepatan menyelesaikan tugas. Anak yang banyak bertanya dianggap menghambat. Orang tua mendukung karena ingin anak disiplin. Analisis hubungan tujuan, pandangan tentang anak, metode, dan bukti keberhasilan.','Unit 1–7'),('uas',16,'UAS · Sintesis keputusan pedagogis','Kepala RA ingin menggunakan aplikasi latihan harian dan mempublikasikan peringkat anak. Sebagian keluarga tidak memiliki perangkat. Seorang anak lebih mampu menjelaskan gagasan melalui gambar dan bermain. Susun keputusan program yang mempertimbangkan tujuan, keadilan, nilai Islam, keluarga, bukti, serta privasi.','Seluruh unit')]:
 b=heading('PERTEMUAN '+str(slot),title,'Panduan latihan asesmen dan rubrik. Penetapan soal resmi, bobot, serta pengumpulan mengikuti arahan dosen.')+f'<article class="reading standalone"><section class="case-box"><span class="eyebrow">KASUS ILUSTRATIF · {scope}</span><h2>Tugas analisis</h2><p>{prompt}</p></section><figure class="scene-figure"><img src="assets/scenes/{"komponen" if name=="uts" else "kontemporer"}.webp" alt="{e(V["komponen" if name=="uts" else "kontemporer"]["alt"])}" width="1536" height="1024" loading="lazy"><figcaption>Ilustrasi rekaan berbantuan AI sebagai pemantik analisis. Gunakan fakta pada uraian kasus untuk menjawab tugas.</figcaption></figure><h2>Langkah kerja</h2><ol><li>Identifikasi fakta, interpretasi, dan informasi yang belum tersedia.</li><li>Rumuskan persoalan pendidikan; jangan memberi diagnosis.</li><li>Gunakan minimal tiga konsep dari unit terkait.</li><li>Bedakan dasar nilai, teori, ketentuan hukum, dan bukti empiris.</li><li>Bandingkan dua alternatif tindakan dan jelaskan pilihan Anda.</li><li>Tentukan bukti untuk meninjau keputusan.</li></ol><p>Usulan format: esai 700–1.000 kata dengan minimal tiga rujukan relevan, termasuk satu sumber resmi. Ini latihan akademik; bukan ketentuan penilaian prodi.</p><h2>Rubrik analitik untuk umpan balik</h2><div class="table-wrap"><table><thead><tr><th>Aspek</th><th>4 · Kuat</th><th>2 · Berkembang</th><th>1 · Perlu dukungan</th></tr></thead><tbody><tr><td>Ketepatan konsep</td><td>Konsep tepat dan hubungan dijelaskan</td><td>Konsep dikenali, hubungan masih lemah</td><td>Definisi keliru atau hanya label</td></tr><tr><td>Analisis kasus</td><td>Fakta, dugaan, dan batas informasi jelas</td><td>Sebagian bukti diperiksa</td><td>Kesimpulan tanpa dasar kasus</td></tr><tr><td>Penggunaan sumber</td><td>Klaim dan jenis sumber sesuai</td><td>Sumber relevan tetapi fungsi belum jelas</td><td>Sitasi tidak mendukung klaim</td></tr><tr><td>Kelayakan tindakan</td><td>Konkret, menghargai anak, dapat ditinjau</td><td>Usulan masuk akal, peninjauan belum rinci</td><td>Usulan umum atau mengabaikan hak anak</td></tr></tbody></table></div><p>Skor 3 digunakan untuk kinerja antara deskripsi 2 dan 4. Maksimum 16; tidak otomatis dikonversi menjadi nilai resmi. Dosen menetapkan penggunaan rubrik.</p><details><summary>Arah pembahasan setelah mencoba</summary><p>Jawaban kuat tidak sekadar menolak program. Jelaskan tujuan yang layak dipertahankan, bagian yang perlu diubah, kebutuhan informasi, dan bukti respons anak. Variasi keputusan dapat diterima bila alasannya tepat dan batas klaimnya jelas.</p></details><a class="button" href="pertemuan.html">Kembali ke materi</a></article>'
 write(name,b,'pertemuan',title)
# Maps, glossary, cases, bibliography, about
b=heading('PETA PEMBELAJARAN','Satu alur, beberapa cara menempuh','Identitas unit tetap. Jadwal dapat dipadatkan tanpa menghilangkan konsep inti.')+'<div class="path-grid"><div><h2>Fondasi</h2><p>Apa itu pendidikan, siapa subjeknya, dan mengapa keputusan perlu landasan?</p></div><div><h2>Konteks AUD</h2><p>Bagaimana konsep diterapkan pada PAUD/RA, nilai Islam, relasi, dan bermain?</p></div><div><h2>Pertimbangan profesional</h2><p>Bagaimana merespons kebudayaan, perubahan sosial, serta kasus kompleks?</p></div></div><h2>Pemetaan pertemuan</h2><div class="table-wrap"><table><thead><tr><th>Pertemuan</th><th>Unit / kegiatan</th><th>Hasil kerja</th></tr></thead><tbody>'
for slot in range(1,17):
 l=next((v for v in L if v['slot']==slot),None)
 b+=f'<tr><td>{slot:02}</td><td><a href="{l["id"] if l else "uts" if slot==8 else "uas"}.html">{e(l["title"]) if l else "UTS" if slot==8 else "UAS"}</a></td><td>{"Analisis kasus dan refleksi" if l else "Esai sintesis"}</td></tr>'
b+='</tbody></table></div><h2>Alternatif pemadatan: 13 kali tatap muka</h2><p>Gabungkan unit tujuan–landasan (3–4), komponen–lingkungan (6–7), dan budaya–kontemporer (13–14). Unit tetap tersedia utuh untuk bacaan mandiri. Urutan UTS/UAS mengikuti kalender aktual; pemetaan ini tidak mengubah RPS resmi secara otomatis.</p><h2>Alokasi belajar yang disarankan: 100 menit</h2><div class="table-wrap"><table><tr><th>Aktivitas</th><th>Menit</th></tr><tr><td>Pemantik dan kasus</td><td>10</td></tr><tr><td>Konsep dan ilustrasi</td><td>30</td></tr><tr><td>Latihan terbimbing</td><td>20</td></tr><tr><td>Analisis mandiri dan diskusi</td><td>30</td></tr><tr><td>Refleksi dan tindak lanjut</td><td>10</td></tr></table></div><p>Penjelasan panjang dapat dibaca sebelum kelas. Durasi adalah rancangan penggunaan, bukan perkiraan kecepatan membaca semua mahasiswa.</p>'
