gloss=[('Akomodasi yang layak','Penyesuaian yang diperlukan agar peserta didik penyandang disabilitas dapat memperoleh akses dan partisipasi pendidikan sesuai kebutuhan.','anak-subjek'),('Asesmen formatif','Pengumpulan dan penggunaan informasi belajar untuk menentukan dukungan atau langkah berikutnya.','komponen'),('DAP','Praktik pendidikan yang mempertimbangkan pola perkembangan, keunikan individu, dan konteks; bukan sekadar kesesuaian usia.','anak-subjek'),('Fakta dan interpretasi','Fakta kasus menyatakan apa yang teramati atau diberikan; interpretasi memberi makna atau penjelasan yang masih perlu diperiksa.','profesional'),('Fitrah','Konsep normatif dalam tradisi Islam yang memerlukan pembacaan sumber; tidak otomatis sama dengan konsep kertas kosong dalam psikologi.','manusia'),('Guided play','Bermain terbimbing: keaktifan dan pilihan anak hadir bersama tujuan serta dukungan pendidik.','bermain'),('Holistik-integratif','Pengembangan AUD melalui pemenuhan kebutuhan yang saling terkait dan koordinasi layanan lintas sektor.','paud'),('Landasan yuridis','Dasar hak, kewajiban, dan ketentuan hukum bagi penyelenggaraan pendidikan.','landasan'),('Mediasi','Perantaraan sosial dan perangkat budaya dalam proses belajar dan perkembangan.','pemikiran'),('Partisipasi','Keterlibatan dan kesempatan menyampaikan suara atau mengambil tindakan yang bermakna.','anak-subjek'),('Refleksi profesional','Peninjauan tindakan pendidik menggunakan konsep, bukti, dan pertimbangan nilai untuk perbaikan.','profesional'),('Scaffolding','Bantuan belajar yang menanggapi kebutuhan tugas dan memungkinkan anak mengambil bagian; atribusi awal pada Wood, Bruner, dan Ross (1976).','pemikiran'),('Stereotip','Penyederhanaan ciri kelompok yang diterapkan kepada individu sehingga dapat membatasi kesempatan.','budaya'),('Tujuan dan indikator','Tujuan adalah arah kemampuan atau nilai; indikator merupakan petunjuk yang dipakai untuk membaca pencapaiannya.','tujuan'),('Zona perkembangan proksimal','Perbedaan antara kemampuan mandiri dan kemampuan melalui bimbingan atau kolaborasi yang sesuai dalam kerangka Vygotsky.','pemikiran')]
